 cards('optMetrics',[['样本外共同观测日',d.observations],['调仓次数 / 方法',d.schedule.length],['最新收缩系数',d.latest.covariance.shrinkage==null?'样本协方差':d.latest.covariance.shrinkage.toFixed(3)],['等权基线收益',pct(base.return)]]);
